function getSystemLanguage() {
    try {
        let lang = GLib.getenv("LANG") || "en";
        if (lang.startsWith("ar"))
            return "ar";
        if (lang.startsWith("fr"))
            return "fr";
        return "en";
    }
    catch (e) {
        return "en";
    }
}
function t(key, lang = "auto", params) {
    let targetLang = lang;
    if (!targetLang || targetLang === "auto") {
        targetLang = getSystemLanguage();
    }
    let dict = TRANSLATIONS[targetLang] || TRANSLATIONS["en"];
    let str = dict[key] || TRANSLATIONS["en"][key] || key;
    if (params) {
        for (let p in params) {
            str = str.replace(new RegExp(`\\{${p}\\}`, "g"), String(params[p]));
        }
    }
    return str;
}
